## Code Example
```javascript
// Issuance (pseudocode)
function issueToken(principal, tenant) {
  const jti = crypto.randomUUID();
  const payload = { iss: tenant, sub: principal.sub, aud: 'api', scope: principal.scope, iat: now(), exp: now()+600, jti, nonce: crypto.randomBytes(16).toString('hex'), tenant };
  const token = signJWT(payload, tenantKey);
  redis.set(`nonce:${tenant}:${jti}`, '1', 'EX', 600);
  return token;
}

// Verification (pseudocode)
function verifyToken(token) {
  const payload = verifyJWT(token);
  if (!redis.exists(`nonce:${payload.tenant}:${payload.jti}`)) throw new Error('Replay');
  return payload;
}
```

